<script setup>
import { updateUser as wayfinderUpdateUser1, users as wayfinderUsers2, storeUser as wayfinderStoreUser3 } from './../../../actions/App/Http/Controllers/Staff/AdminOperationsController';

import { users as usersRoute } from '../../../actions/App/Http/Controllers/Staff/AdminOperationsController';
import { router, useForm } from '@inertiajs/vue3';
import { reactive, ref, watch } from 'vue';
import StaffAdminLayout from '../../../Layouts/StaffAdminLayout.vue';

const props = defineProps({ users: Object, roles: Array, filters: Object });
const q = ref(props.filters.q || '');
const create = useForm({ name: '', email: '', password: '', password_confirmation: '', role: 'student' });
const drafts = reactive({});
function hydrate() { props.users.data.forEach((user) => { drafts[user.id] = { role: user.roles[0]?.name || 'student', is_active: Boolean(user.is_active), bio: user.bio || '', avatar_path: user.avatar_path || '', avatar_upload: null }; }); }
watch(() => props.users.data, hydrate, { immediate: true });
function save(id) { router.patch(wayfinderUpdateUser1.url({ user: id }), drafts[id], { preserveScroll: true }); }
let timer;
watch(q, (value) => { clearTimeout(timer); timer = setTimeout(() => router.get(wayfinderUsers2().url, { q: value }, { preserveState: true, preserveScroll: true, replace: true }), 250); });
</script>

<template><StaffAdminLayout><div class="admin-heading"><div><div class="eyebrow">PEOPLE & PERMISSIONS</div><h1>People and access.</h1><p>Create accounts, set a single primary role, and maintain public mentor profile details. Disabled accounts cannot sign in.</p></div></div>
  <section class="admin-panel"><h2>Create an account</h2><form class="admin-form" @submit.prevent="create.post(wayfinderStoreUser3().url)"><div class="admin-form-grid"><label>Full name<input v-model="create.name" required><small class="admin-form-error">{{ create.errors.name }}</small></label><label>Email<input v-model="create.email" type="email" required><small class="admin-form-error">{{ create.errors.email }}</small></label></div><div class="admin-form-grid"><label>Temporary password<input v-model="create.password" type="password" minlength="12" required><small>At least 12 characters.</small><small class="admin-form-error">{{ create.errors.password }}</small></label><label>Confirm password<input v-model="create.password_confirmation" type="password" required></label></div><div class="admin-form-grid"><label>Primary role<select v-model="create.role"><option v-for="role in roles" :key="role.id" :value="role.name">{{ role.label }}</option></select></label><div class="create-account-submit"><button class="button button-dark" :disabled="create.processing">Create account <UiIcon name="arrow-up-right" :size="13"/></button></div></div></form></section>
  <section class="admin-panel"><div class="people-toolbar"><h2>Accounts <span class="admin-chip">{{ users.total }}</span></h2><input v-model="q" type="search" placeholder="Search by name or email" aria-label="Search people"></div><div class="people-list"><article v-for="user in users.data" :key="user.id" class="person-card"><div class="person-summary"><span class="person-initials">{{ user.name.split(' ').map((part) => part[0]).slice(0,2).join('') }}</span><span><b>{{ user.name }}</b><small>{{ user.email }} · Joined {{ new Date(user.created_at).toLocaleDateString() }}</small></span><span class="admin-chip" :class="user.is_active ? 'status-published' : 'status-archived'">{{ user.is_active ? 'active' : 'disabled' }}</span></div><div class="person-edit"><label>Primary role<select v-model="drafts[user.id].role"><option v-for="role in roles" :key="role.id" :value="role.name">{{ role.label }}</option></select></label><label>Mentor bio<textarea v-model="drafts[user.id].bio" rows="2" maxlength="4000" placeholder="Displayed on the public mentor profile when this person teaches a course."></textarea></label><label>Replace avatar<input type="file" accept="image/jpeg,image/png,image/webp" @input="drafts[user.id].avatar_upload = $event.target.files[0] || null"><small>Square image · JPG, PNG, or WebP · up to 2 MB.</small></label><label class="person-active"><input v-model="drafts[user.id].is_active" type="checkbox"> Account enabled</label><button class="button button-dark" type="button" @click="save(user.id)">Save access & profile</button></div></article><div v-if="!users.data.length" class="admin-empty">No accounts found.</div></div><div class="admin-pagination"><span>Page {{ users.current_page }} of {{ users.last_page }}</span><div><a v-if="users.prev_page_url"  :href="usersRoute.url({mergeQuery: {page: users.current_page - 1}})">← Newer</a><a v-if="users.next_page_url"  :href="usersRoute.url({mergeQuery: {page: users.current_page + 1}})">Older →</a></div></div></section>
</StaffAdminLayout></template>

<style scoped>.people-toolbar{display:flex;align-items:center;justify-content:space-between;gap:18px}.people-toolbar h2{margin:0}.people-toolbar input{padding:10px;border:1px solid #e2e1da;border-radius:6px;min-width:260px}.person-card{border-top:1px solid #efeee9;margin-top:18px;padding-top:16px}.person-summary{display:flex;align-items:center;gap:12px}.person-summary>span:nth-child(2){flex:1;display:grid;gap:4px}.person-summary small{color:#7b8178}.person-initials{width:38px;height:38px;border-radius:50%;background:#eceee7;display:grid;place-items:center;color:#596d51}.person-edit{display:grid;grid-template-columns:1fr 2fr 1.4fr auto auto;align-items:end;gap:10px;margin:16px 0 0 50px}.person-edit label{display:grid;gap:5px;font-size:11px;color:#687066}.person-edit input:not([type=checkbox]),.person-edit textarea,.person-edit select{width:100%;padding:9px;border:1px solid #e2e1da;border-radius:6px;font:inherit}.person-edit .person-active{display:flex;align-items:center;white-space:nowrap}.person-edit .button{font-size:10px;padding:10px;white-space:nowrap}.create-account-submit{display:flex;align-items:end}.admin-pagination{display:flex;justify-content:space-between;margin-top:15px;font-size:11px;color:#71796f}.admin-pagination div{display:flex;gap:14px}.admin-pagination a{color:#53684a}@media(max-width:1000px){.person-edit{margin-left:0;grid-template-columns:1fr 1fr}.person-edit label:nth-child(2){grid-column:span 2}}@media(max-width:600px){.people-toolbar{align-items:flex-start;flex-direction:column}.people-toolbar input{min-width:100%}.person-edit{grid-template-columns:1fr}.person-edit label:nth-child(2){grid-column:auto}.person-summary small{word-break:break-word}.person-summary>.admin-chip{display:none}}
</style>
